/* ===== Danh sách ô ===== */
export function drBuildPads(): DrPad[] {
  const out: DrPad[] = [], jcts = drJunctions();
  for (const j of jcts) out.push({ id: j.id, kind: 'junction', x0: j.x0, x1: j.x1, z0: j.z0, z1: j.z1, y: flat });
