import { pathToFileURL } from 'node:url';
import fs from 'node:fs';
const root = 'D:/2026 - Tuan/danang-vite/';
const { serveDir, launch, openApp, frames, pick } = await import(pathToFileURL(root + 'tests/lib.mjs').href);
fs.mkdirSync(root + 'tests/screens', { recursive: true });
const srv = await serveDir(root + 'dist/');
const browser = await launch();
const out = (n) => root + 'tests/screens/drive-hud-' + n + '.png';
async function shot(page, name, x, z, yaw, v) {
  await page.evaluate(([x, z, yaw, v]) => {
    const d = window.__app.drive; d.placeAt(x, z, yaw); d.state.v = v;
    d.step(0.016, { gas: 0, brake: 0, steer: 0, hand: false });
  }, [x, z, yaw, v]);
  await frames(page, 2); await new Promise((r) => setTimeout(r, 400));
  await page.evaluate(() => { const d = window.__app.drive; d.step(0.016, { gas: 0, brake: 0, steer: 0, hand: false }); });
  await frames(page, 1);
  await page.screenshot({ path: out(name) });
  console.log('shot', name, await page.evaluate(() => ({ kmh: document.getElementById('drKmh').textContent, map: [document.getElementById('drMap').width, document.getElementById('drMap').height] })));
}
try {
  const D = await openApp(browser, srv.url + '?explore=drive', { width: 1280, height: 720 });
  await shot(D.page, 'desk-dragon', -150, 8.6, 0, 13.9);
  await shot(D.page, 'desk-tp', 200, -2900 + 4, Math.PI, 27.78);
  console.log(D.errors);
  await D.page.close();
  const P = await openApp(browser, srv.url + '?explore=drive', { width: 390, height: 844, mobile: true });
  await shot(P.page, 'phone-portrait', -150, 8.6, 0, 13.9);
  await pick(P.page, '#langSelect', 'ar'); await P.page.evaluate(() => window.__app.ui.closeSheets());
  await shot(P.page, 'phone-portrait-ar', 200, -2900 + 4, Math.PI, 8);
  console.log(P.errors);
  await P.page.close();
  const L = await openApp(browser, srv.url + '?explore=drive', { width: 844, height: 390, mobile: true });
  await shot(L.page, 'phone-land', -150, 8.6, 0, 13.9);
  await pick(L.page, '#langSelect', 'ar'); await L.page.evaluate(() => window.__app.ui.closeSheets());
  await shot(L.page, 'phone-land-ar', -150, 8.6, 0, 13.9);
  console.log(L.errors);
  await L.page.close();
} finally { await browser.close(); srv.close(); }

